import sys, os, openpyxl
inp = os.environ['IN_XLSX']
outp = os.environ['OUT_XLSX']
d = os.path.dirname(outp)
if d and not os.path.isdir(d):
    os.makedirs(d, exist_ok=True)
wb = openpyxl.load_workbook(inp)
s1 = wb['Sheet1']; s2 = wb['Sheet2']

def rows(ws):
    res = []
    for r in range(9, ws.max_row+1):
        vals = [ws.cell(row=r, column=c).value for c in range(1,8)]
        if all(v is None for v in vals):
            continue
        res.append(tuple(vals))
    return res

r1 = rows(s1); r2 = rows(s2)
set2 = set(r2); set1 = set(r1)

def unique(seq, other):
    seen = set(); out = []
    for t in seq:
        if t not in other and t not in seen:
            seen.add(t); out.append(t)
    return out

sub = unique(r1, set2)
add = unique(r2, set1)

for name, data in [('Sheet3', sub), ('Sheet4', add)]:
    ws = wb[name]
    for r in range(1, ws.max_row+1):
        for c in range(1,8):
            ws.cell(row=r, column=c).value = None
    for i, t in enumerate(data):
        for c, v in enumerate(t):
            ws.cell(row=i+1, column=c+1).value = v

wb.save(outp)
print('saved to', outp, os.path.exists(outp))
